package main

// JavaScript-faithful copies of the n8n Code nodes. The live node code is kept
// in testdata/n8n/ and main_test.go checks this file against it (fixtures
// generated by gen-fixtures.js running the real node code in Node.js).

import (
	"encoding/json"
	"math"
	"regexp"
	"strconv"
	"strings"
	"unicode/utf16"
)

type source struct {
	ID    string `json:"id"`
	Title string `json:"title"`
	Text  string `json:"text"`
}

type input struct {
	Message    string        `json:"message"`
	History    []chatMessage `json:"history"`
	Sources    []source      `json:"sources"`
	HasSources bool          `json:"hasSources"`
	Valid      bool          `json:"valid"`
}

// validate = node "Validasi Pesan".
func validate(body any) input {
	b := body
	if !truthy(b) {
		b = map[string]any{}
	}
	in := input{History: []chatMessage{}, Sources: []source{}}
	if m, ok := field(b, "message").(string); ok {
		in.Message = jsTrim(m)
	}
	if hist, ok := field(b, "history").([]any); ok {
		if len(hist) > 6 {
			hist = hist[len(hist)-6:]
		}
		for _, h := range hist {
			role, _ := field(h, "role").(string)
			content, isStr := field(h, "content").(string)
			if !truthy(h) || (role != "user" && role != "assistant") || !isStr {
				continue
			}
			in.History = append(in.History, chatMessage{Role: role, Content: jsSlice(content, 1200)})
		}
	}
	if srcs, ok := field(b, "sources").([]any); ok {
		if len(srcs) > 12 {
			srcs = srcs[:12]
		}
		for _, s := range srcs {
			id, idOK := field(s, "id").(string)
			text, textOK := field(s, "text").(string)
			if !truthy(s) || !idOK || !textOK {
				continue
			}
			in.Sources = append(in.Sources, source{
				ID:    jsSlice(id, 80),
				Title: jsSlice(jsString(field(s, "title")), 160),
				Text:  jsSlice(text, 1600),
			})
		}
	}
	in.HasSources = len(in.Sources) > 0
	n := jsLen(in.Message)
	in.Valid = n > 0 && n <= 1200
	return in
}

// knowledgeSources = the "no website sources" branch of node "Susun Prompt".
func knowledgeSources(kb any) []source {
	if !truthy(kb) {
		kb = map[string]any{}
	}
	out := []source{}
	srcs, ok := field(kb, "sources").([]any)
	if !ok {
		return out
	}
	if len(srcs) > 12 {
		srcs = srcs[:12]
	}
	for _, s := range srcs {
		id, idOK := field(s, "id").(string)
		text, textOK := field(s, "text").(string)
		if !truthy(s) || !idOK || !textOK {
			continue
		}
		out = append(out, source{ID: id, Title: jsString(field(s, "title")), Text: jsSlice(text, 1600)})
	}
	return out
}

type checked struct {
	OK         bool     `json:"ok"`
	Diagnostic string   `json:"diagnostic"`
	Reply      string   `json:"reply"`
	Handoff    bool     `json:"handoff"`
	SourceIDs  []string `json:"source_ids"`
	// Thrown: the JS code would throw (n8n then fails the whole execution).
	Thrown bool `json:"-"`
}

// JS \s: WhiteSpace + LineTerminator. Go's \s is ASCII-only, so spell it out.
const jsWS = `\t\n\x{0b}\f\r \x{a0}\x{1680}\x{2000}-\x{200a}\x{2028}\x{2029}\x{202f}\x{205f}\x{3000}\x{feff}`

var (
	reFence  = regexp.MustCompile("(?i)```(?:json)?")
	reMdLink = regexp.MustCompile(`\[([^\]]+)\]\([^)]*\)`)
	reURL    = regexp.MustCompile(`(?i)https?://[^` + jsWS + `]+|www\.[^` + jsWS + `]+|wa\.me[^` + jsWS + `]*`)
	reTag    = regexp.MustCompile(`<[^>]*>`)
	reBold   = regexp.MustCompile(`\*\*`)
)

func fail(d string) checked {
	return checked{OK: false, Diagnostic: d, Reply: "", Handoff: true, SourceIDs: []string{}}
}

// checkAnswer = nodes "Periksa Jawaban" and "Periksa Cadangan" (identical code).
func checkAnswer(item any, allowed map[string]bool) checked {
	if !truthy(item) {
		item = map[string]any{}
	}
	if e := field(item, "error"); truthy(e) {
		v := field(e, "code")
		if !truthy(v) {
			v = field(e, "type")
		}
		if !truthy(v) {
			v = field(e, "message")
		}
		if !truthy(v) {
			v = "x"
		}
		return fail("groq_error:" + jsSlice(jsString(v), 80))
	}
	var text any
	if c := field(item, "choices"); truthy(c) {
		if c0 := index0(c); truthy(c0) {
			if m := field(c0, "message"); truthy(m) {
				text = field(m, "content")
			}
		}
	}
	t, ok := text.(string)
	if !ok {
		return fail("groq_no_content")
	}
	var p any
	if err := json.Unmarshal([]byte(jsTrim(reFence.ReplaceAllString(t, ""))), &p); err != nil {
		return fail("groq_bad_json")
	}
	if p == nil {
		// JS: null.reply throws TypeError.
		return checked{Thrown: true}
	}
	reply, _ := field(p, "reply").(string)
	reply = reMdLink.ReplaceAllString(reply, "${1}")
	reply = reURL.ReplaceAllString(reply, "")
	reply = reTag.ReplaceAllString(reply, "")
	reply = reBold.ReplaceAllString(reply, "")
	reply = jsSlice(jsTrim(reply), 2400)
	handoff := field(p, "handoff") == true
	ids := []string{}
	if arr, ok := field(p, "source_ids").([]any); ok {
		seen := map[string]bool{}
		for _, v := range arr {
			if id, ok := v.(string); ok && allowed[id] && !seen[id] {
				seen[id] = true
				ids = append(ids, id)
			}
		}
		if len(ids) > 8 {
			ids = ids[:8]
		}
	}
	if !handoff && reply == "" {
		return fail("groq_empty")
	}
	if !handoff && len(ids) == 0 {
		if !allowed["site:overview"] {
			return fail("groq_no_sources")
		}
		ids = []string{"site:overview"}
	}
	if reply == "" {
		reply = "Baik."
	}
	if handoff {
		ids = []string{}
	}
	return checked{OK: true, Diagnostic: "groq_ok", Reply: reply, Handoff: handoff, SourceIDs: ids}
}

// --- JavaScript value helpers -------------------------------------------

func field(v any, k string) any {
	if m, ok := v.(map[string]any); ok {
		return m[k]
	}
	return nil
}

func index0(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) > 0 {
			return x[0]
		}
	case map[string]any:
		return x["0"]
	}
	return nil
}

func truthy(v any) bool {
	switch x := v.(type) {
	case nil:
		return false
	case bool:
		return x
	case float64:
		return x != 0 && !math.IsNaN(x)
	case string:
		return x != ""
	}
	return true
}

// jsString = String(v || '').
func jsString(v any) string {
	if !truthy(v) {
		return ""
	}
	return jsToString(v)
}

// jsToString = String(v) for JSON values.
func jsToString(v any) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case string:
		return x
	case bool:
		return strconv.FormatBool(x)
	case float64:
		return jsNumber(x)
	case []any:
		parts := make([]string, len(x))
		for i, e := range x {
			if e != nil {
				parts[i] = jsToString(e)
			}
		}
		return strings.Join(parts, ",")
	}
	return "[object Object]"
}

func jsNumber(f float64) string {
	a := math.Abs(f)
	if a != 0 && (a >= 1e21 || a < 1e-6) {
		s := strconv.FormatFloat(f, 'e', -1, 64)
		s = strings.Replace(s, "e-0", "e-", 1)
		s = strings.Replace(s, "e+0", "e+", 1)
		return s
	}
	return strconv.FormatFloat(f, 'f', -1, 64)
}

func isJSSpace(r rune) bool {
	switch r {
	case '\t', '\n', '\v', '\f', '\r', ' ', 0xa0, 0x1680, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0xfeff:
		return true
	}
	return r >= 0x2000 && r <= 0x200a
}

func jsTrim(s string) string { return strings.TrimFunc(s, isJSSpace) }

// jsLen / jsSlice count UTF-16 code units like String.prototype.length/slice.
func jsLen(s string) int { return len(utf16.Encode([]rune(s))) }

func jsSlice(s string, n int) string {
	u := utf16.Encode([]rune(s))
	if len(u) <= n {
		return s
	}
	return string(utf16.Decode(u[:n]))
}
